rule.definition:
a!localVariables(
  local!userData: #"SYSTEM_SYSRULES_queryRecordType_v4"(
    recordType: #"urn:appian:record-type:v1:SYSTEM_RECORD_TYPE_USER",
    fields: {
      #"urn:appian:record-field:v1:SYSTEM_RECORD_TYPE_USER/SYSTEM_RECORD_TYPE_USER_FIELD_username",
      #"urn:appian:record-field:v1:SYSTEM_RECORD_TYPE_USER/SYSTEM_RECORD_TYPE_USER_FIELD_firstName",
      #"urn:appian:record-field:v1:SYSTEM_RECORD_TYPE_USER/SYSTEM_RECORD_TYPE_USER_FIELD_lastName"
    },
    pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(startIndex: 1, batchSize: 100)
  ).data,
  local!users: #"SYSTEM_SYSRULES_forEach"(
    items: local!userData,
    expression: a!map(
      username: fv!item[#"urn:appian:record-field:v1:SYSTEM_RECORD_TYPE_USER/SYSTEM_RECORD_TYPE_USER_FIELD_username"],
      firstName: fv!item[#"urn:appian:record-field:v1:SYSTEM_RECORD_TYPE_USER/SYSTEM_RECORD_TYPE_USER_FIELD_firstName"],
      lastName: fv!item[#"urn:appian:record-field:v1:SYSTEM_RECORD_TYPE_USER/SYSTEM_RECORD_TYPE_USER_FIELD_lastName"]
    )
  ),
  #"SYSTEM_SYSRULES_httpResponse_v1"(
    statusCode: 200,
    headers: {
      #"SYSTEM_SYSRULES_httpHeader"(
        name: "Content-Type",
        value: "application/json"
      )
    },
    body: #"SYSTEM_SYSRULES_toJson_v1"(
      a!map(
        success: true,
        totalCount: length(local!users),
        users: local!users
      )
    )
  )
)
